arguments.command:
bash -lc "set -euo pipefail
{
  find /etc -maxdepth 4 \( -path '*/openvpn*' -o -path '*/vpn*' -o -path '*/NetworkManager/system-connections*' \) -type f \( -iname '*.ovpn' -o -iname '*.conf' \) -print 2>/dev/null || true
  find /root /home -maxdepth 6 -type f \( -iname '*.ovpn' -o -iname '*.conf' \) -path '*/.config/*' -print 2>/dev/null || true
} | sort -u"
